    def __init__(self):
        self.generation = 0
        self.rows = []
        self.decisions = {}
        self.busy = False
        self._latest_completed_generation = None
        self._has_fetched_results = False

    def start(self):
        self.generation += 1
        self.busy = True
        return self.generation

    def poll_status(self, generation, status):
        if generation != self.generation or not self.busy:
            return False

        if status == 'completed':
            if self._latest_completed_generation == generation:
                return False
            self._latest_completed_generation = generation
            self._has_fetched_results = True
            return True

        if status == 'failed':
            self.busy = False
            return False

        return False

    def finish(self, generation, rows):
        if self.busy and generation == self.generation and self._has_fetched_results and self._latest_completed_generation == generation:
            self.rows = list(rows)
            self.busy = False
            self._latest_completed_generation = None # prevent duplicate finish
            self._has_fetched_results = False
            return True
        return False

    def set_decision(self, job_id, value):
        self.decisions[job_id] = value
